// On-demand LinkedIn text: follow the user prompt.
// Web research always runs on create, with a hard time budget so the function never hangs.
import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { resolveTextProvider, xaiErrorMessage } from "../_shared/ai-text.ts";
import { resolveProjectFirecrawlKey } from "../_shared/firecrawl.ts";
import { gatherSourceContext, scrapeUrl, type SourceInput } from "../_shared/web-sources.ts";
import { resolveContentSkill, skillTextBlock } from "../_shared/content-skills.ts";
import { buildAnalysisMaterial } from "../_shared/market-analysis.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};
const json = (s: number, b: unknown) =>
  new Response(JSON.stringify(b), { status: s, headers: { ...corsHeaders, "Content-Type": "application/json" } });

const SITE_ALIASES: Record<string, string> = {
  reuters: "reuters.com",
  bloomberg: "bloomberg.com",
  cnbc: "cnbc.com",
  "financial times": "ft.com",
  ft: "ft.com",
  wsj: "wsj.com",
  eia: "eia.gov",
};

function extractPreferredSites(prompt: string): string[] {
  const lower = prompt.toLowerCase();
  const sites = new Set<string>();
  for (const [alias, host] of Object.entries(SITE_ALIASES)) {
    if (lower.includes(alias)) sites.add(host);
  }
  if (/sources?\s+fiables|reliable\s+sources|bourses?/i.test(prompt)) {
    for (const host of ["reuters.com", "bloomberg.com", "cnbc.com", "eia.gov"]) sites.add(host);
  }
  return [...sites];
}

function buildResearchKeywords(prompt: string): SourceInput[] {
  const sites = extractPreferredSites(prompt);
  const siteFilter = sites.length ? `(${sites.map((s) => `site:${s}`).join(" OR ")})` : "";

  let topic = prompt
    .replace(/n['']invente[\s\S]*$/i, "")
    .replace(/(puis|then)\s+(écris|write|rédige)[\s\S]*$/i, "")
    .replace(/écris\s+un\s+post[\s\S]*$/i, "")
    .replace(/write\s+a\s+(linkedin\s+)?post[\s\S]*$/i, "")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 120);

  if (!topic) topic = prompt.replace(/\s+/g, " ").trim().slice(0, 100);

  const queries: string[] = [];
  if (topic) queries.push(siteFilter ? `${topic} ${siteFilter}` : topic);

  if (/commodit|marché|market|oil|brent|wti|gas|gold|copper|wheat/i.test(prompt)) {
    queries.push(
      siteFilter
        ? `commodity market movers today prices ${siteFilter}`
        : "commodity market movers today oil gas gold copper wheat",
    );
  }

  const seen = new Set<string>();
  const out: SourceInput[] = [];
  for (const q of queries) {
    const key = q.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ type: "keyword", value: q.slice(0, 180) });
    if (out.length >= 3) break;
  }
  return out;
}

async function scrapeTopArticles(
  urls: string[],
  firecrawlKey?: string | null,
  limit = 2,
): Promise<string> {
  const unique = [...new Set(urls)]
    .filter((u) => /^https?:\/\//i.test(u))
    .filter((u) => !/google\.com\/search|duckduckgo\.com/i.test(u))
    .slice(0, limit);

  const chunks: string[] = [];
  await Promise.all(unique.map(async (url) => {
    try {
      const md = await scrapeUrl(url, firecrawlKey);
      if (md && md.length > 120) chunks.push(`# Article: ${url}\n\n${md.substring(0, 2000)}`);
    } catch { /* ignore */ }
  }));
  return chunks.join("\n\n---\n\n");
}

serve(async (req) => {
  // CORS must always answer instantly — never do research on OPTIONS.
  if (req.method === "OPTIONS") {
    return new Response(null, { status: 204, headers: corsHeaders });
  }

  try {
    const body = await req.json();
    const {
      prompt,
      currentText,
      imageUrl,
      mode,
      sources,
      savedSourceIds,
      useMemory = false,
      analysis,
      researchLog,
      news,
      chartOnly = false,
    } = body;

    const supabase = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
    const auth = req.headers.get("Authorization");
    if (!auth) return json(401, { success: false, error: "Unauthorized" });
    const { data: u } = await supabase.auth.getUser(auth.replace("Bearer ", ""));
    const userId = u.user?.id;
    if (!userId) return json(401, { success: false, error: "Unauthorized" });

    const { data: s } = await supabase.from("user_settings")
      .select("post_model, use_byok, openai_api_key, xai_api_key, gemini_api_key, firecrawl_api_key, tone_instructions, active_skill")
      .eq("user_id", userId).maybeSingle();

    const automated = useMemory === true;
    let resolvedSources: SourceInput[] = Array.isArray(sources) ? sources : [];

    if (Array.isArray(savedSourceIds) && savedSourceIds.length) {
      const { data: saved } = await supabase
        .from("content_sources")
        .select("id, source_type, value")
        .eq("user_id", userId)
        .in("id", savedSourceIds);
      for (const r of saved || []) {
        if (r.source_type === "url" || r.source_type === "keyword" || r.source_type === "idea") {
          resolvedSources.push({ type: r.source_type as SourceInput["type"], value: r.value });
        }
      }
    }

    if (automated && !resolvedSources.length) {
      const { data: enabled } = await supabase
        .from("content_sources")
        .select("source_type, value")
        .eq("user_id", userId)
        .eq("enabled", true)
        .limit(6);
      for (const r of enabled || []) {
        if (r.source_type === "url" || r.source_type === "keyword" || r.source_type === "idea") {
          resolvedSources.push({ type: r.source_type as SourceInput["type"], value: r.value });
        }
      }
    }

    const promptText = typeof prompt === "string" ? prompt.trim() : "";

    // Step-2 mode: an approved analysis + research log replaces web research entirely.
    const hasAnalysis = typeof analysis === "string" && analysis.trim().length > 100;

    if (!hasAnalysis && mode !== "improve" && promptText.length >= 8) {
      const hasExplicit = resolvedSources.some((x) => x.type === "url" || x.type === "keyword");
      if (!hasExplicit) resolvedSources = [...resolvedSources, ...buildResearchKeywords(promptText)];
    }

    let sourceContext = "";
    let sourceProvider: "firecrawl" | "open" = "open";
    let researchUrls: string[] = [];
    let queryCount = 0;
    let hitCount = 0;

    if (hasAnalysis) {
      sourceContext = buildAnalysisMaterial(analysis, researchLog, news);
    }

    if (!hasAnalysis && mode !== "improve" && resolvedSources.length) {
      queryCount = resolvedSources.filter((x) => x.type === "keyword").length;
      const firecrawlKey = await resolveProjectFirecrawlKey(supabase, s?.firecrawl_api_key);

      console.log("compose-text research start", {
        queries: queryCount,
        hasFirecrawl: !!firecrawlKey,
      });

      try {
        const gathered = await Promise.race([
          gatherSourceContext(resolvedSources, {
            firecrawlKey,
            maxUrls: 3,
            maxKeywords: 3,
            urlSnippetChars: 1800,
            budgetMs: 12000,
          }),
          new Promise<{ context: string; freshUrls: string[]; provider: "firecrawl" | "open"; hitCount: number }>((resolve) =>
            setTimeout(() => resolve({ context: "", freshUrls: [], provider: firecrawlKey ? "firecrawl" : "open", hitCount: 0 }), 14000)
          ),
        ]);
        sourceContext = gathered.context;
        sourceProvider = gathered.provider;
        researchUrls = gathered.freshUrls;
        hitCount = gathered.hitCount;

        if (researchUrls.length && sourceContext.length < 4000) {
          const articles = await Promise.race([
            scrapeTopArticles(researchUrls, firecrawlKey, 2),
            new Promise<string>((resolve) => setTimeout(() => resolve(""), 8000)),
          ]);
          if (articles) {
            sourceContext = [sourceContext, articles].filter(Boolean).join("\n\n---\n\n").substring(0, 18000);
          }
        }
      } catch (e) {
        console.warn("compose-text research error", e);
      }

      console.log("compose-text research done", {
        provider: sourceProvider,
        urls: researchUrls.length,
        hits: hitCount,
        contextLen: sourceContext.length,
      });
    }

    const { model, url, key } = resolveTextProvider(s?.post_model || "google/gemini-3-flash-preview", s);
    const hasResearch = sourceContext.trim().length > 40;
    const tone = automated && s?.tone_instructions?.trim() ? s.tone_instructions.trim() : "";
    const skill = resolveContentSkill(s?.active_skill);
    const skillBlock = skillTextBlock(skill);

    const sys = `Follow the user's instructions exactly. Write the LinkedIn post they asked for.
${skill
  ? "An active content skill is attached below — follow its structure, branding, and hard rules (they override generic defaults). Also fill image_python with a NEW matplotlib script adapted to this analysis (brand reference only — do not copy a fixed template)."
  : "Do not add branding, CTAs, hashtags, emojis, length rules, or structure unless the user requested them."}
Return JSON via the write_post tool (title + content${skill ? " + image_python when possible" : ""}).
${tone ? `\nAutomation voice/memory from settings:\n${tone}` : ""}${skillBlock}
${hasAnalysis
  ? "AN APPROVED MARKET ANALYSIS AND RESEARCH LOG ARE ATTACHED below (already researched and verified). Write ONLY from them: no new facts, no new numbers, no web knowledge. The image_python script must plot only figures from the research log; invent a layout for THIS day."
  : hasResearch
    ? "WEB RESEARCH IS ATTACHED below. Ground every figure and factual claim ONLY in that research. Prefer outlets the user named. If a number is missing, omit it — never invent. image_python must use the same research only."
    : "Web research returned no usable snippets. Write a short honest note without inventing prices. Set image_python to null."}${
  chartOnly ? "\nIMAGE ONLY: the existing post is provided; keep its content exactly and focus on writing a fresh image_python script for it." : ""}`;

    const sourceBlock = hasResearch
      ? `\n\n${hasAnalysis ? "" : "--- Web research (use for facts/figures only) ---\n"}${sourceContext.substring(0, 16000)}${hasAnalysis ? "" : "\n--- End research ---"}`
      : "";

    let userMsg: unknown;
    if (chartOnly && currentText) {
      userMsg = `Existing LinkedIn post (keep as is in content):\n\n${currentText}\n\nWrite a NEW CommoHedge matplotlib script (image_python) adapted to this analysis — brand colours/wordmark as inspiration only, invent today's layout.${sourceBlock}`;
    } else if (mode === "improve" && currentText) {
      userMsg = `Improve this LinkedIn draft according to the instructions.\n\nDraft:\n${currentText}\n\nInstructions: ${promptText || "Polish clarity and flow."}${sourceBlock}`;
    } else if (imageUrl) {
      userMsg = [
        { type: "text", text: `${promptText || "Write a LinkedIn post about this image."}${sourceBlock}` },
        { type: "image_url", image_url: { url: imageUrl } },
      ];
    } else {
      userMsg = `${promptText || "Write a LinkedIn post."}${sourceBlock}`;
    }

    const res = await fetch(url, {
      method: "POST",
      headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
      body: JSON.stringify({
        model,
        messages: [{ role: "system", content: sys }, { role: "user", content: userMsg }],
        tools: [{
          type: "function",
          function: {
            name: "write_post",
            description: skill
              ? "Return the LinkedIn post and a fresh CommoHedge matplotlib image_python script"
              : "Return the LinkedIn post",
            parameters: {
              type: "object",
              properties: {
                title: { type: "string", description: "Short internal title" },
                content: { type: "string", description: "Full LinkedIn post body as requested" },
                ...(skill
                  ? {
                    image_python: {
                      anyOf: [
                        { type: "null" },
                        {
                          type: "string",
                          description:
                            "Brand-new matplotlib script for THIS analysis (inspiration: CommoHedge palette/wordmark only). Must savefig(OUT). Null if no reliable figures.",
                        },
                      ],
                    },
                  }
                  : {}),
              },
              required: ["title", "content"],
              additionalProperties: false,
            },
          },
        }],
        tool_choice: { type: "function", function: { name: "write_post" } },
      }),
    });
    if (!res.ok) {
      if (url.startsWith("https://api.x.ai/")) return json(res.status, { success: false, error: xaiErrorMessage(res.status) });
      if (res.status === 429) return json(429, { success: false, error: "Rate limit exceeded." });
      if (res.status === 402) return json(402, { success: false, error: "Add credits to your workspace." });
      const t = await res.text();
      return json(500, { success: false, error: `AI error [${res.status}]: ${t}` });
    }

    const data = await res.json();
    const tc = data.choices?.[0]?.message?.tool_calls?.[0];
    if (!tc) return json(500, { success: false, error: "AI returned no structured data" });
    const out = JSON.parse(tc.function.arguments);
    const imagePython =
      typeof out.image_python === "string" && out.image_python.trim().length > 80
        ? out.image_python.trim()
        : null;
    return json(200, {
      success: true,
      title: out.title,
      content: chartOnly && typeof currentText === "string" && currentText.trim() ? currentText : out.content,
      imagePython,
      chart: null,
      usedAnalysis: hasAnalysis,
      usedSources: resolvedSources.length,
      sourceProvider,
      hadWebContext: hasResearch,
      researchRequested: true,
      queryCount,
      hitCount,
      researchUrlCount: researchUrls.length,
      usedFirecrawl: sourceProvider === "firecrawl",
      usedMemory: automated,
    });
  } catch (e) {
    console.error("compose-text error", e);
    return json(500, { success: false, error: e instanceof Error ? e.message : "Failed" });
  }
});

export type TextSettings = {
  use_byok?: boolean;
  openai_api_key?: string | null;
  xai_api_key?: string | null;
  gemini_api_key?: string | null;
};

function requireByok(settings: TextSettings | null) {
  if (!settings?.use_byok) {
    throw new Error("Active tes propres clés API (BYOK) dans les paramètres pour générer du contenu.");
  }
}

/** Route text generation to the user's BYOK provider (xAI / OpenAI / Gemini). No shared gateway. */
export function resolveTextProvider(model: string, settings: TextSettings | null) {
  if (model.startsWith("xai/")) {
    requireByok(settings);
    if (!settings?.xai_api_key?.trim()) {
      throw new Error("Ajoute et enregistre ta clé API xAI dans les paramètres pour utiliser Grok.");
    }
    return {
      model: model.slice(4),
      url: "https://api.x.ai/v1/chat/completions",
      key: settings.xai_api_key.trim(),
    };
  }

  if (model.startsWith("openai/")) {
    requireByok(settings);
    if (!settings?.openai_api_key?.trim()) {
      throw new Error("Ajoute et enregistre ta clé API OpenAI dans les paramètres.");
    }
    return {
      model: model.slice(7),
      url: "https://api.openai.com/v1/chat/completions",
      key: settings.openai_api_key.trim(),
    };
  }

  if (model.startsWith("google/")) {
    requireByok(settings);
    if (!settings?.gemini_api_key?.trim()) {
      throw new Error("Ajoute et enregistre ta clé API Google Gemini dans les paramètres.");
    }
    return {
      model: model.replace(/^google\//, ""),
      url: "https://generativelanguage.googleapis.com/v1beta/openai/chat/completions",
      key: settings.gemini_api_key.trim(),
    };
  }

  throw new Error(
    `Modèle non supporté: ${model}. Choisis un modèle Gemini, OpenAI ou Grok dans les réglages (BYOK).`,
  );
}

export function normalizeGrokModels(models: unknown, modality: "text" | "image" = "text"): { value: string; label: string }[] {
  if (!Array.isArray(models)) return [];
  const ids = new Set<string>();
  for (const model of models) {
    if (!model || typeof model !== "object") continue;
    const { id, aliases, output_modalities } = model as {
      id?: unknown;
      aliases?: unknown;
      output_modalities?: unknown;
    };
    if (Array.isArray(output_modalities) && !output_modalities.includes(modality)) continue;
    for (const name of [id, ...(Array.isArray(aliases) ? aliases : [])]) {
      if (typeof name === "string" && /^[a-zA-Z0-9._-]+$/.test(name)) ids.add(name);
    }
  }
  return [...ids].sort().map((id) => ({ value: `xai/${id}`, label: `Grok · ${id} (API xAI)` }));
}

export function xaiErrorMessage(status: number) {
  if (status === 401) return "Clé API xAI invalide ou expirée. Remplace-la dans les paramètres.";
  if (status === 402) return "Crédits xAI insuffisants. Recharge ton compte xAI.";
  if (status === 403) return "Accès xAI refusé : vérifie les permissions de ta clé et l’accès au modèle.";
  if (status === 404) return "Ce modèle Grok n’est plus disponible. Actualise la liste dans les paramètres.";
  if (status === 429) return "Limite de requêtes xAI atteinte. Réessaie plus tard.";
  if (status === 503) return "Le modèle Grok est temporairement surchargé. Réessaie plus tard.";
  return `La requête xAI a échoué (${status}). Vérifie le modèle et réessaie.`;
}

/** Resolve Firecrawl API key: user BYOK → env secret → project automation_config. */
export async function resolveProjectFirecrawlKey(
  supabase: { from: (t: string) => any },
  userKey?: string | null,
): Promise<string | null> {
  const fromUser = (userKey ?? "").trim();
  if (fromUser) return fromUser;

  const fromEnv = (Deno.env.get("FIRECRAWL_API_KEY") ?? "").trim();
  if (fromEnv) return fromEnv;

  try {
    const { data } = await supabase
      .from("automation_config")
      .select("firecrawl_api_key")
      .eq("id", 1)
      .maybeSingle();
    const fromProject = (data?.firecrawl_api_key ?? "").trim();
    return fromProject || null;
  } catch (e) {
    console.warn("resolveProjectFirecrawlKey failed", e);
    return null;
  }
}

/**
 * Web source gathering: Firecrawl when a key is available, otherwise free open fallbacks
 * (Jina Reader for URLs, Google News RSS + DuckDuckGo HTML for keyword search).
 * All network calls are hard-timeouted so edge functions never hang.
 */

export type SourceInput = { type: "url" | "keyword" | "idea"; value: string };

export type GatherOptions = {
  firecrawlKey?: string | null;
  maxUrls?: number;
  maxKeywords?: number;
  usedUrls?: Set<string>;
  urlSnippetChars?: number;
  /** Hard budget for the whole gather (ms). */
  budgetMs?: number;
};

function resolveFirecrawlKey(explicit?: string | null): string {
  return (explicit ?? "").trim() || (Deno.env.get("FIRECRAWL_API_KEY") ?? "").trim();
}

async function fetchWithTimeout(
  input: string,
  init: RequestInit = {},
  timeoutMs = 8000,
): Promise<Response> {
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), timeoutMs);
  try {
    return await fetch(input, { ...init, signal: ctrl.signal });
  } finally {
    clearTimeout(t);
  }
}

function stripTags(html: string): string {
  return html
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, " ")
    .trim();
}

function decodeXml(s: string): string {
  return s
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, "$1")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");
}

export type SearchHit = { title: string; description: string; url: string };

function normalizeHits(raw: unknown[]): SearchHit[] {
  return raw
    .map((item) => {
      if (!item || typeof item !== "object") return null;
      const x = item as Record<string, unknown>;
      const url = String(x.url || x.link || x.sourceURL || "").trim();
      if (!url) return null;
      return {
        title: String(x.title || x.name || "").trim(),
        description: String(x.description || x.snippet || x.markdown || "").trim().slice(0, 500),
        url,
      };
    })
    .filter((x): x is SearchHit => !!x);
}

/** Scrape a single URL → markdown/text. */
export async function scrapeUrl(url: string, firecrawlKey?: string | null): Promise<string | null> {
  const fc = resolveFirecrawlKey(firecrawlKey);
  if (fc) {
    try {
      const r = await fetchWithTimeout("https://api.firecrawl.dev/v2/scrape", {
        method: "POST",
        headers: { Authorization: `Bearer ${fc}`, "Content-Type": "application/json" },
        body: JSON.stringify({ url, formats: ["markdown"], onlyMainContent: true, waitFor: 800 }),
      }, 10000);
      if (r.ok) {
        const d = await r.json();
        const md = d.data?.markdown || d.markdown;
        if (md) return String(md);
      } else {
        console.warn("firecrawl scrape status", r.status);
      }
    } catch (e) {
      console.warn("firecrawl scrape fail", url, String(e));
    }
  }

  try {
    const r = await fetchWithTimeout(`https://r.jina.ai/${url}`, {
      headers: { Accept: "text/plain", "User-Agent": "market-pulse-poster/1.0" },
    }, 8000);
    if (r.ok) {
      const text = await r.text();
      if (text.trim().length > 80) return text;
    }
  } catch (e) {
    console.warn("jina scrape fail", url, String(e));
  }

  try {
    const r = await fetchWithTimeout(url, {
      headers: { "User-Agent": "Mozilla/5.0 (compatible; MarketPulseBot/1.0)", Accept: "text/html" },
      redirect: "follow",
    }, 6000);
    if (!r.ok) return null;
    const html = await r.text();
    const text = stripTags(html);
    return text.length > 80 ? text : null;
  } catch (e) {
    console.warn("raw scrape fail", url, String(e));
    return null;
  }
}

async function searchGoogleNews(query: string, limit: number): Promise<SearchHit[]> {
  const rssUrl =
    `https://news.google.com/rss/search?q=${encodeURIComponent(query)}&hl=en-US&gl=US&ceid=US:en`;
  const r = await fetchWithTimeout(rssUrl, {
    headers: { "User-Agent": "Mozilla/5.0 (compatible; MarketPulseBot/1.0)", Accept: "application/rss+xml, application/xml, text/xml" },
  }, 7000);
  if (!r.ok) return [];
  const xml = await r.text();
  const items = [...xml.matchAll(/<item>([\s\S]*?)<\/item>/gi)].slice(0, limit + 2);
  const hits: SearchHit[] = [];
  for (const m of items) {
    const block = m[1];
    const title = decodeXml((block.match(/<title>([\s\S]*?)<\/title>/i)?.[1] || "").trim());
    const link = decodeXml((block.match(/<link>([\s\S]*?)<\/link>/i)?.[1] || "").trim());
    const desc = stripTags(decodeXml((block.match(/<description>([\s\S]*?)<\/description>/i)?.[1] || "").trim()));
    if (link) hits.push({ title, description: desc.slice(0, 400), url: link });
  }
  return hits.slice(0, limit);
}

async function searchFirecrawl(query: string, firecrawlKey: string, limit: number): Promise<SearchHit[]> {
  const r = await fetchWithTimeout("https://api.firecrawl.dev/v2/search", {
    method: "POST",
    headers: { Authorization: `Bearer ${firecrawlKey}`, "Content-Type": "application/json" },
    body: JSON.stringify({ query, limit: Math.max(limit, 5), tbs: "qdr:w" }),
  }, 10000);
  const text = await r.text();
  if (!r.ok) {
    console.warn("firecrawl search status", r.status, text.slice(0, 200));
    return [];
  }
  let d: Record<string, unknown> = {};
  try { d = JSON.parse(text); } catch { return []; }
  const data = d.data;
  let raw: unknown[] = [];
  if (Array.isArray(data)) raw = data;
  else if (data && typeof data === "object") {
    const obj = data as Record<string, unknown>;
    if (Array.isArray(obj.web)) raw = obj.web;
    else if (Array.isArray(obj.results)) raw = obj.results;
  }
  return normalizeHits(raw).slice(0, limit);
}

/** Keyword web search → Firecrawl first (if key), then Google News. */
export async function searchKeyword(query: string, firecrawlKey?: string | null, limit = 3): Promise<SearchHit[]> {
  const fc = resolveFirecrawlKey(firecrawlKey);
  if (fc) {
    try {
      const hits = await searchFirecrawl(query, fc, limit);
      if (hits.length) {
        console.log("firecrawl search ok", { q: query.slice(0, 60), hits: hits.length });
        return hits;
      }
    } catch (e) {
      console.warn("firecrawl search fail", String(e));
    }
  }

  try {
    const hits = await searchGoogleNews(query, limit);
    if (hits.length) {
      console.log("google news ok", { q: query.slice(0, 60), hits: hits.length });
      return hits;
    }
  } catch (e) {
    console.warn("google news fail", String(e));
  }

  console.warn("searchKeyword empty", { q: query.slice(0, 60), hadFirecrawl: !!fc });
  return [];
}

/** Build markdown context from mixed sources. Honors budgetMs. */
export async function gatherSourceContext(
  sources: SourceInput[],
  opts: GatherOptions = {},
): Promise<{ context: string; freshUrls: string[]; provider: "firecrawl" | "open"; hitCount: number }> {
  const firecrawlKey = resolveFirecrawlKey(opts.firecrawlKey);
  const provider = firecrawlKey ? "firecrawl" : "open";
  const maxUrls = opts.maxUrls ?? 3;
  const maxKeywords = opts.maxKeywords ?? 3;
  const snippet = opts.urlSnippetChars ?? 1800;
  const used = opts.usedUrls ?? new Set<string>();
  const budgetMs = opts.budgetMs ?? 15000;
  const deadline = Date.now() + budgetMs;

  const chunks: string[] = [];
  const freshUrls: string[] = [];
  let hitCount = 0;

  const ideas = sources.filter((s) => s.type === "idea").map((s) => s.value).filter(Boolean);
  if (ideas.length) chunks.push(`# Ideas / notes from the user\n\n${ideas.map((i) => `- ${i}`).join("\n")}`);

  const urls = sources.filter((s) => s.type === "url").map((s) => s.value).filter(Boolean).slice(0, maxUrls);
  const keywords = sources.filter((s) => s.type === "keyword").map((s) => s.value).filter(Boolean).slice(0, maxKeywords);

  // Keywords first (fast headlines), then optional URL scrapes if time remains.
  for (const kw of keywords) {
    if (Date.now() > deadline) break;
    try {
      const results = await searchKeyword(kw, firecrawlKey, used.size ? 4 : 3);
      const fresh = results.filter((x) => x.url && !used.has(x.url)).slice(0, 3);
      if (!fresh.length) continue;
      hitCount += fresh.length;
      chunks.push(`# Search: ${kw}\n\n${fresh.map((x) => `- ${x.title}: ${x.description} (${x.url})`).join("\n")}`);
      for (const x of fresh) freshUrls.push(x.url);
    } catch (e) {
      console.warn("keyword gather fail", String(e));
    }
  }

  await Promise.all(urls.map(async (url) => {
    if (Date.now() > deadline) return;
    try {
      const md = await scrapeUrl(url, firecrawlKey);
      if (md) {
        chunks.push(`# Source: ${url}\n\n${md.substring(0, snippet)}`);
        freshUrls.push(url);
        hitCount++;
      }
    } catch (e) {
      console.warn("url gather fail", String(e));
    }
  }));

  return { context: chunks.join("\n\n---\n\n"), freshUrls, provider, hitCount };
}

